def calculate_tr(high, low, prev_close):
    return max(high - low, abs(high - prev_close), abs(low - prev_close))

calculate_tr(12.0, 10.0, 10.5)

def donchian_channel(prices, window=20):
    if len(prices) <= window:
        return None
    history = prices[-window-1:-1]
    return (max(history), min(history))

donchian_channel([10, 12, 11, 15, 14, 13], window=3)

def calculate_zscore(spread, mean, std):
    if std <= 0:
        return 0.0
    return (spread - mean) / std

calculate_zscore(12.0, 10.0, 2.0)

import math

def calculate_half_life(lambda_param):
    if lambda_param <= 0:
        return 0.0
    return math.log(2) / lambda_param

calculate_half_life(0.69314718)

