import math

def calculate_ir(ic, breadth):
    if breadth <= 0:
        return 0.0
    return ic * math.sqrt(breadth)

calculate_ir(0.05, 400)

def clip_by_bounds(values, lower_val, upper_val):
    return [max(lower_val, min(upper_val, x)) for x in values]

clip_by_bounds([1.0, 5.0, 10.0, -2.0], 0.0, 8.0)
